import { Attribute, Component, ElementRef, HostAttributeToken, HostBinding, inject, Renderer2 } from '@angular/core';

@Component({
  selector: 'pct-avatar',
  templateUrl: './avatar.html',
})
export class PctAvatar {
  private readonly el = inject(ElementRef).nativeElement as HTMLElement;
  private readonly renderer = inject(Renderer2);
  private readonly given = inject(new HostAttributeToken('tabindex'), {
    optional: true,
  });
  @HostBinding('attr.tabindex') protected readonly order = 0;

  constructor(@Attribute('tabindex') readonly said: string | null) {
    this.el.getAttribute('tabindex');
    this.el.getAttributeNS(null, 'tabindex');
    this.el.hasAttribute('tabindex');
    this.el.hasAttributeNS(null, 'tabindex');
    this.el.toggleAttribute('tabindex');
    this.el.removeAttribute('tabindex');
    this.el.removeAttributeNS(null, 'tabindex');
    this.el.setAttribute('tabindex', '0');
    this.el.setAttributeNS(null, 'tabindex', '-1');
    this.renderer.setProperty(this.el, 'tabIndex', 0);
    this.el.setAttribute('tabindex', '5');
  }
}
